import logging
from functools import wraps

from .adapters import SwamSoapAdapter
from .converters import convert_module, convert_report

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


def log_request_response(operation):
    """
    Log raw API request and response.
    """

    @wraps(operation)
    def wrapper(*args, **kwargs):
        """
        :return: API response
        """
        logger.info(f'Request to {operation.__name__!r} sent with parameters "{args[1:]} {kwargs}".')
        response = operation(*args, **kwargs)
        logger.info(f'Response: {response}')
        return response

    return wrapper


class Service:
    NAME: str

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        if not hasattr(cls, 'NAME'):
            raise AttributeError(f"{cls.__name__!r} must have a 'NAME' attribute")

    def __init__(self, web_url, username, password):
        self.soap_api = SwamSoapAdapter(self.NAME, web_url, username, password)


class ConfigurationService(Service):
    NAME = 'OpenSWAMConfigurationServiceSOAP'

    @log_request_response
    def delete_module_configuration(self, module_id):
        """
        :param int module_id:
        """
        self.soap_api.service.deleteModuleConfiguration(id=module_id)

    @log_request_response
    def get_all_module_configuration(self):
        """
        Return only non-mandatory modules.

        ModuleConfigurationService.get_all_module_configuration is preferred, this endpoint is a backup.

        :rtype: list(dict)
        """
        return self.soap_api.service.getAllModuleConfiguration()

    @log_request_response
    def get_module_configuration(self, module_id):
        """
        :param int module_id:
        :return: module
        :rtype: dict
        """
        return convert_module(self.soap_api.service.getModuleConfiguration(id=module_id))

    @log_request_response
    def insert_module_configuration(self, **module):
        """
        :param dict module:
        :return: inserted module
        :rtype: dict
        """
        dto = self.soap_api.core_type_factory.moduleConfigurationDto(**module)
        return self.soap_api.service.insertModuleConfiguration(moduleConfiguration=dto)

    @log_request_response
    def update_module_configuration(self, **module):
        """
        :param dict module:
        :return: inserted module
        :rtype: dict
        """
        dto = self.soap_api.core_type_factory.moduleConfigurationDto(**module)
        return self.soap_api.service.updateModuleConfiguration(moduleConfiguration=dto)


class DefinitionsService(Service):
    NAME = 'DefinitionsService'

    @log_request_response
    def get_definitions_as_disabled(self, **definition_query):
        """
        :return: definitions
        :rtype: list(dict)
        """
        definition_query = self._build_definition_query(**definition_query)
        return self.soap_api.service.getDefinitionsAsDisabled(definitionQuery=definition_query)

    @log_request_response
    def get_definitions_as_enabled(self, **definition_query):
        """
        :return: definitions
        :rtype: list(dict)
        """
        definition_query = self._build_definition_query(**definition_query)
        return self.soap_api.service.getDefinitionsAsEnabled(definitionQuery=definition_query)

    def _build_definition_query(self, measurement_type, technology, ps2only,
                                data_volume=None, ps_trigger=None, ps_calculation=None):
        """
        :param string measurement_type: validation.types.common['measurementType']
        :param string technology: validation.types.common['technology']
        :param bool ps2only: validation.types.common['ps2Only']
        :param string data_volume: validation.types.common['dataVolume']
        :param string ps_trigger: validation.types.common['psTrigger']
        :param string ps_calculation: validation.types.common['psCalculation']
        :return: definition query
        :rtype: SwamSoapAdapter.core_type_factory.definitionQuery
        """
        return self.soap_api.core_type_factory.definitionQuery(
            type=measurement_type,
            technology=technology,
            ps2only=ps2only,
            dataVolume=data_volume,
            psTrigger=ps_trigger,
            psCalculation=ps_calculation
        )


class ModuleConfigurationService(Service):
    NAME = 'ModuleConfigurationService'

    @log_request_response
    def get_all_module_configuration(self):
        """
        Return a list of all mandatory and non-mandatory modules.

        :rtype: list(dict)
        """
        return self.soap_api.service.getAllModuleConfiguration()


class PmCmDataService(Service):
    NAME = 'PMCMDataService'

    def delete_all_reports(self):
        """
        Delete all reports.
        """
        self.soap_api.service.deleteAllReports()

    @log_request_response
    def generate_reports(self, module_id, day, trigger):
        """
        :param int module_id:
        :param datetime.date day:
        :param trigger: validation.types.other_types['generateReportTrigger']
        :return: task id
        :rtype: int
        """
        day = self.soap_api.core_type_factory.localDateWrapper(date=day)
        return self.soap_api.service.generateReports(moduleId=module_id, day=day, trigger=trigger)


class ReportingService(Service):
    NAME = 'OpenSWAMReportingServiceSOAP'

    @log_request_response
    def get_filtered_reports(self, measurement_type=None, technology=None,
                             report_detail_level=None, start_day=None, end_day=None):
        """
        :param string measurement_type: types._common_types['measurementType']
        :param string technology: types._common_types['measurementType']
        :param string report_detail_level: types.report_types['reportDetailLevel']
        :param datetime.date start_day:
        :param datetime.date end_day:
        :return: reports
        :rtype: list(dict)
        """
        conditions = self.soap_api.core_type_factory.reportFilteringConditions(
            measurementType=measurement_type,
            technology=technology,
            reportDetailLevel=report_detail_level,
            startDay=start_day,
            endDay=end_day
        )
        reports = self.soap_api.service.getFilteredReports(reportFilteringConditions=conditions)
        return [convert_report(report) for report in reports]

    @log_request_response
    def generate_reports(self, module):
        """
        This endpoint cannot be used to generate reports for existing module.
        Instead module is created from given configuration and deleted after generation finishes.

        PmCmDataService.generate_reports is preferred, this endpoint is a backup.

        :param dict module:
        :return: task id
        :rtype: int
        """
        return self.soap_api.service.generateReports(moduleConfiguration=module)

    @log_request_response
    def get_report_with_rows(self, report_id):
        """
        :param int report_id:
        :return: detailed report
        :rtype: dict
        """
        report = self.soap_api.service.getReportWithRows(id=report_id)
        return convert_report(report)

    @log_request_response
    def get_task_status(self, task_id):
        """
        :param int task_id:
        :return: task status
        :rtype: dict
        """
        return self.soap_api.service.getTaskStatus(taskId=task_id)
